<script>
import { House, Info, Mail } from '@lucide/vue'

// Page behaviour: hero waves, plane fly-in, floating balloon girl, Join us clouds and sky,
// team carousel (arrows, dots, drag, auto-slide), shrinking header, mobile menu,
// smooth in-page links, footer logo slide-in and the contact thank-you popup.
export default {
  components: { House, Info, Mail },
  data() {
    return { tmLoop: false, tmIdx: 0, contactSending: false }
  },
  computed: {
    team() {
      const team = [
      { name: 'Alex Fenton', past: 'Multi-exited founder and entrepreneur', present: 'Head cheerleader', photo: '/images/team/alex.png', pos: '50% 100%', noPhoto: false, link: 'https://www.linkedin.com/' },
      { name: 'Charlotte', past: 'M&A Analyst', present: 'Group Head of Operations', photo: '/images/team/charlotte.png', pos: '50% 25%', noPhoto: false, link: 'https://www.linkedin.com/in/charlottejames97/' },
      { name: 'Mbali', past: 'CRM & Marketing', present: 'Founders Associate', photo: '/images/team/mbali.png', pos: '50% 25%', noPhoto: false, link: 'https://www.linkedin.com/in/mbali-sibisi-0435461b5/' },
      { name: 'Juliet', past: 'Marketing Consultant', present: 'Growth and Marketing Manager', photo: '/images/team/juliet.png', pos: '50% 0%', noPhoto: false, link: 'https://www.linkedin.com/in/julietmey/' },
      { name: 'Tayla-Jade', past: 'HR Officer', present: 'People & Culture Manager', photo: '/images/team/tayla-jade.png', pos: '50% 50%', noPhoto: false, link: 'https://www.linkedin.com/in/tayla-jade-teixeira-548177176/' },
      { name: 'Lindyn', past: 'Recruitment Consultant', present: 'People & Culture Administrator', photo: '/images/team/lindyn.png', pos: '50% 25%', noPhoto: false, link: 'https://www.linkedin.com/in/lindyn-ross-7aaba4252/' },
      { name: 'Lauren', past: 'GTM Engineer', present: 'GTM Manager', photo: '/images/team/lauren.png', pos: '50% 20%', noPhoto: false, link: 'https://www.linkedin.com/in/lauren-gracie-989664165/' },
      { name: 'Michael', past: 'Account Manager', present: 'Digital Marketing Manager', photo: '/images/team/michael.png', pos: '50% 10%', noPhoto: false, link: 'https://www.linkedin.com/in/michael-dawson-51439a70/' },
      { name: 'FC', past: 'Finance & Operations Manager', present: 'Group Finance Manager', photo: '/images/team/fc.png', pos: '50% 0%', noPhoto: false, link: 'https://www.linkedin.com/in/fc-schlebusch-b66156151/' },
      { name: 'Suvaal', past: 'Audit Senior', present: 'Senior Financial Accountant', photo: '/images/team/suvaal.png', pos: '50% 10%', noPhoto: false, link: 'https://www.linkedin.com/in/suvaal-ramdutt-42289b27a/' },
      { name: 'Austin', past: 'GTM Engineer', present: 'GTM Technical Operations Engineer', photo: '/images/team/austin.png', pos: '68% 50%', noPhoto: false, link: 'https://www.linkedin.com/in/austin-fernandez-992338284/' },
      { name: 'Nicayla', past: 'Social Media & Content Intern', present: 'Social Media Content Specialist', photo: '/images/team/nicayla.png', pos: '50% 20%', noPhoto: false, link: 'https://www.linkedin.com/in/nicayla-de-villiers-588618228/' },
      { name: 'Chulu', past: 'Junior Marketing Coordinator', present: 'Operations Executive', photo: '/images/team/chulu.png', pos: '50% 20%', noPhoto: false, link: 'https://www.linkedin.com/in/chulumanconxibi/' }
      ];
      return team
    },
    // three runs of the team so the carousel can loop; the outer two are copies, added after load
    teamCards() {
      const run = (copy, at) => this.team.map((m, i) => ({ ...m, copy, key: at + i }));
      return this.tmLoop ? [...run(true, 'a'), ...run(false, 'r'), ...run(true, 'c')] : run(false, 'r');
    },
    teamDots() {
      return Array.from({ length: this.team.length }, (_, i) => ({
        label: 'Go to team slide ' + (i + 1),
        w: i === this.tmIdx ? '28px' : '10px',
        bg: i === this.tmIdx ? '#FF66CC' : '#B9BBC2',
        go: () => this.teamGo(i),
      }))
    },
  },
  mounted() {
    this.plStage = this.$refs.plStage
    this.girlBox = this.$refs.girlBox
    this.whySec = this.$refs.whySec
    this.teamTrack = this.$refs.teamTrack
    const menu = document.getElementById('m-menu');
    if (menu) {
    // picking a link closes the menu (the page then glides to that section)
    this.onMenuPick = (e) => { if (e.target.closest && e.target.closest('a')) this.setMenu(false); };
    menu.addEventListener('click', this.onMenuPick);
    }
    this.onMenuKey = (e) => { if (e.key === 'Escape') this.setMenu(false); };
    window.addEventListener('keydown', this.onMenuKey);
    this.onMenuResize = () => { if (window.innerWidth > 767) this.setMenu(false); this.heroRest(); };
    window.addEventListener('resize', this.onMenuResize, { passive: true });
    this.onThanksKey = (e) => { if (e.key === 'Escape') { this.closeThanks(); this.closeFail(); } };
    window.addEventListener('keydown', this.onThanksKey);
    this.onAnchor = (e) => {
    const a = e.target.closest && e.target.closest('a[href^="#"]');
    if (!a) return;
    const el = document.getElementById(a.getAttribute('href').slice(1));
    if (!el) return;
    e.preventDefault();
    const calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let box = null;
    for (let n = el.parentElement; n && !box; n = n.parentElement) {
    const s = getComputedStyle(n);
    if (/(auto|scroll)/.test(s.overflowY) && n.scrollHeight > n.clientHeight) box = n;
    }
    const root = document.scrollingElement || document.documentElement;
    box = box || root;
    const hdr = document.querySelector('.ev header');
    // land on the section's content (24px of its top padding stays) just under the bar's final height:
    // heading down the page the bar slims to 66px, heading up it opens to its full 88px (phones keep 66px)
    const full = window.innerWidth <= 767 ? 66 : 88;
    const spot = () => {
    const base = box === root ? 0 : box.getBoundingClientRect().top;
    const pad = el.id === 'top' ? 0 : Math.max(0, parseFloat(getComputedStyle(el).paddingTop) - 24);
    return el.getBoundingClientRect().top - base + box.scrollTop + pad;
    };
    const down = spot() - 66 > box.scrollTop;
    const aim = () => { const to = spot(); return Math.max(0, Math.round(to - (!hdr ? 0 : down && to - 66 >= 120 ? 66 : full))); };
    box.scrollTo({ top: aim(), behavior: calm ? 'auto' : 'smooth' });
    // the page may still be loading: check the aim once the glide has really stopped, unless the visitor took over
    let mine = true;
    const off = () => { mine = false; };
    ['wheel', 'touchstart', 'keydown'].forEach((ev) => window.addEventListener(ev, off, { once: true, passive: true }));
    setTimeout(() => {
    const y = box.scrollTop;
    setTimeout(() => {
    ['wheel', 'touchstart', 'keydown'].forEach((ev) => window.removeEventListener(ev, off));
    const t = aim();
    if (mine && box.scrollTop === y && Math.abs(y - t) > 2) box.scrollTo({ top: t, behavior: calm ? 'auto' : 'smooth' });
    }, 120);
    }, 1100);
    };
    window.addEventListener('click', this.onAnchor, true);
    this.setupNavShrink();
    // this.setupSectionSnap();   // section snapping switched off while debugging scroll feel
    this.onTeamResize = () => this.measureTeam();
    window.addEventListener('resize', this.onTeamResize, { passive: true });
    this.measureTeam();
    // the copies go in after load, so the page HTML stays light; start on the middle run, before anything paints
    this.tmLoop = true;
    this.$nextTick(() => {
    this.measureTeam();
    if (this.teamTrack) this.teamTrack.scrollTo({ left: this.tmBase + this.tmW, behavior: 'instant' });
    });
    this.setupTeamDrag();
    this.setupGroupCards();
    this.startTeamAuto();
    // footer group logos slide in when the footer comes into view, and again on the next pass down
    const fl = document.querySelector('.foot-logos');
    if (fl && 'IntersectionObserver' in window) {
    this.ioLogos = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
    if (e.isIntersecting) fl.classList.add('in');
    else if (e.boundingClientRect.top > 0) fl.classList.remove('in');
    });
    }, { threshold: 0.4 });
    this.ioLogos.observe(fl);
    } else if (fl) fl.classList.add('in');
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.calmMotion = reduce;
    this.heroRest();
    const hero = document.getElementById('top');
    if (hero && 'IntersectionObserver' in window) {
    this.ioHero = new IntersectionObserver((entries) => { this.heroAway = !entries[entries.length - 1].isIntersecting; this.heroRest(); });
    this.ioHero.observe(hero);
    }
    const s = this.plStage;
    if (!s) return;
    if (!reduce) this.floatGirl();
    if (!reduce) this.cloudsOut();
    if (reduce) { this.fly(-10); return; }
    if ('IntersectionObserver' in window) {
    this.io = new IntersectionObserver((entries) => {
    if (entries.some((e) => e.isIntersecting)) { this.fly(0); this.io.disconnect(); }
    }, { threshold: 0, rootMargin: '0px 0px -20% 0px' });
    this.io.observe(s);
    } else {
    this.fly(0);
    }
  },
  beforeUnmount() {
    if (this.onMenuKey) window.removeEventListener('keydown', this.onMenuKey);
    if (this.onMenuResize) window.removeEventListener('resize', this.onMenuResize);
    if (this.onThanksKey) window.removeEventListener('keydown', this.onThanksKey);
    if (this.navTarget) this.navTarget.removeEventListener('scroll', this.onNavScroll);
    if (this.snapTarget) this.snapTarget.removeEventListener('scroll', this.onSnapScroll);
    if (this.onSnapStop) ['wheel', 'touchstart', 'keydown', 'pointerdown'].forEach((ev) => window.removeEventListener(ev, this.onSnapStop));
    if (this.tmAuto) clearInterval(this.tmAuto);
    clearTimeout(this.tmIdle);
    if (this.ioTeam) this.ioTeam.disconnect();
    if (this.tmGlide) cancelAnimationFrame(this.tmGlide);
    if (this.onAnchor) window.removeEventListener('click', this.onAnchor, true);
    if (this.io) this.io.disconnect();
    if (this.ioHero) this.ioHero.disconnect();
    if (this.ioLogos) this.ioLogos.disconnect();
    if (this.roCards) this.roCards.disconnect();
    if (this.onTeamResize) window.removeEventListener('resize', this.onTeamResize);
    if (this.onTeamMove) {
    window.removeEventListener('pointermove', this.onTeamMove);
    window.removeEventListener('pointerup', this.onTeamUp);
    window.removeEventListener('pointercancel', this.onTeamUp);
    }
    if (this.onCloudScroll) {
    document.removeEventListener('scroll', this.onCloudScroll, { capture: true });
    window.removeEventListener('resize', this.onCloudScroll);
    }
    if (this.onGirlScroll) {
    document.removeEventListener('scroll', this.onGirlScroll, { capture: true });
    window.removeEventListener('resize', this.onGirlScroll);
    }
  },
  methods: {
    // the waves rest when nobody can see them: hero off screen, or the phone menu open over it
    heroRest() {
    const hero = document.getElementById('top');
    const art = document.querySelector('.hero-art');
    if (!hero || !art || !art.pauseAnimations) return;
    const rest = !!(this.heroAway || this.menuOpen);
    hero.classList.toggle('rest', rest);
    // phones show the pre-drawn layers, so the live SVG never needs to run there
    if (rest || this.calmMotion || window.innerWidth <= 767) art.pauseAnimations(); else art.unpauseAnimations();
    },
    fly(at) {
    const s = this.plStage;
    if (s) s.classList.add(at < 0 ? 'done' : 'go');
    },
    floatGirl() {
    const girl = this.girlBox;
    if (!girl) return;
    const sec = girl.closest('section');
    if (!sec) return;
    let queued = false, raf = 0, cy = null, cs = 0, ty = 0, ts = 0;
    // she trails her scroll target slightly, so the rise reads as a float rather than being glued to the page
    const glide = () => {
    cy += (ty - cy) * 0.09;
    cs += (ts - cs) * 0.09;
    girl.style.transform = 'translateY(' + cy.toFixed(1) + 'px) rotate(' + cs.toFixed(2) + 'deg)';
    raf = Math.abs(ty - cy) > 0.4 || Math.abs(ts - cs) > 0.02 ? requestAnimationFrame(glide) : 0;
    };
    const update = () => {
    queued = false;
    const r = sec.getBoundingClientRect();
    const vh = window.innerHeight || 800;
    const p = Math.min(1, Math.max(0, (vh - r.top) / (vh + r.height)));
    const secH = sec.offsetHeight;
    const h = girl.offsetHeight;
    ty = (1 - p) * (secH * 0.82) - p * (h * 0.65);    // from low in the section to just above its top
    ts = Math.sin(p * Math.PI * 3) * 4;
    if (cy === null) { cy = ty; cs = ts; }
    if (!raf) raf = requestAnimationFrame(glide);
    };
    this.onGirlScroll = () => { if (!queued) { queued = true; requestAnimationFrame(update); } };
    document.addEventListener('scroll', this.onGirlScroll, { passive: true, capture: true });
    window.addEventListener('resize', this.onGirlScroll, { passive: true });
    update();
    },
    cloudsOut() {
    const sec = this.whySec;
    if (!sec) return;
    const els = Array.from(sec.querySelectorAll('[data-ev-out]'));
    const sky = sec.querySelector('.join-sky');
    if (!els.length) return;
    let queued = false;
    const update = () => {
    queued = false;
    const vh = window.innerHeight || 800;
    const r = sec.getBoundingClientRect();
    const clamp = (k) => Math.min(1, Math.max(0, k));
    const ease = (k) => k * k * (3 - 2 * k);
    const inP = ease(clamp((vh - r.top) / vh));                   // drift in over a full screen of scrolling
    const dist = Math.max(window.innerWidth * 0.16, 220);
    els.forEach((el) => {
    const f = +el.getAttribute('data-ev-out');                   // bigger number = travels further, so the clouds separate
    const x = (1 - inP) * dist * f;
    const y = -(1 - inP) * 30;
    el.style.transform = 'translate(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px)';
    el.style.opacity = Math.min(1, inP * 1.5).toFixed(3);
    });
    if (sky) sky.style.opacity = inP.toFixed(3);              // the clouds bring the grey sky in with them
    };
    this.onCloudScroll = () => { if (!queued) { queued = true; requestAnimationFrame(update); } };
    document.addEventListener('scroll', this.onCloudScroll, { passive: true, capture: true });
    window.addEventListener('resize', this.onCloudScroll, { passive: true });
    update();
    },
    // the logo has to clear each card's details panel, and how tall that is depends on how its text wraps
    setupGroupCards() {
    const group = document.getElementById('portfolio');
    const cards = [...document.querySelectorAll('.card')];
    if (!group || !cards.length || !('ResizeObserver' in window)) return;
    this.roCards = new ResizeObserver(() => {
    let tallest = 0;
    for (const card of cards) {
    const h = card.querySelector('.d-info').offsetHeight;
    card.style.setProperty('--info', h + 'px');
    tallest = Math.max(tallest, h);
    }
    group.style.setProperty('--info-max', tallest + 'px');
    });
    cards.forEach((card) => this.roCards.observe(card.querySelector('.d-info')));
    },
    measureTeam() {
    const t = this.teamTrack;
    if (!t) return;
    const c = t.querySelectorAll('.tm-card');
    if (c.length < 2) return;
    const n = this.team.length;
    const first = c[0].getBoundingClientRect().left;
    this.tmStep = c[1].getBoundingClientRect().left - first;
    this.tmBase = first - t.getBoundingClientRect().left + t.scrollLeft;
    this.tmW = this.tmStep * n;
    const idx = ((Math.round((t.scrollLeft - this.tmBase) / this.tmStep) % n) + n) % n;
    if (this.tmIdx !== idx) this.tmIdx = idx;
    },
    // maps any position on to the same view inside the middle run; the runs are identical, so the jump can't be seen
    teamWrap(x) {
    if (!this.tmLoop || !this.tmW) return x;
    const lo = this.tmW + this.tmBase - this.tmStep / 2;
    return lo + (((x - lo) % this.tmW) + this.tmW) % this.tmW;
    },
    // native swipes and arrow keys can't be wrapped mid-scroll, so bring them back once they stop or a finger lands
    teamRecentre() {
    const t = this.teamTrack;
    if (!t || this.tmGlide || this.tmHeld) return;
    const to = this.teamWrap(t.scrollLeft);
    if (Math.abs(to - t.scrollLeft) > 1) t.scrollTo({ left: to, behavior: 'instant' });
    },
    teamGlide(left, dur, quick) {
    const t = this.teamTrack;
    if (!t) return;
    // positions in a glide keep counting past the end of a run; teamWrap maps them back on to the cards
    const from = this.tmGlide ? this.tmAt : t.scrollLeft;
    if (this.tmGlide) cancelAnimationFrame(this.tmGlide);
    this.tmGlide = 0;
    const dist = left - from;
    if (Math.abs(dist) < 1) { t.style.scrollSnapType = 'x mandatory'; t.style.scrollBehavior = 'smooth'; return; }
    this.tmTo = left;
    this.tmAt = from;
    const t0 = performance.now();
    // a tap mid-glide has to move at once, so it only eases out; a glide from rest eases in and out
    const ease = quick ? (x) => 1 - Math.pow(1 - x, 3) : (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
    t.style.scrollSnapType = 'none';
    t.style.scrollBehavior = 'auto';
    const frame = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    this.tmAt = from + dist * ease(k);
    t.scrollLeft = this.teamWrap(this.tmAt);
    if (k < 1) { this.tmGlide = requestAnimationFrame(frame); return; }
    this.tmGlide = 0;
    t.style.scrollSnapType = 'x mandatory';
    t.style.scrollBehavior = 'smooth';
    };
    this.tmGlide = requestAnimationFrame(frame);
    },
    teamMove(dir) {
    const t = this.teamTrack;
    if (!t) return;
    // a tap during a glide counts on from where the glide is heading, so quick taps stack up and speed it along
    const busy = !!this.tmGlide;
    const k = Math.round(((busy ? this.tmTo : t.scrollLeft) - this.tmBase) / this.tmStep) + dir;
    this.teamGlide(this.tmBase + k * this.tmStep, busy ? 500 : 900, busy);
    },
    teamGo(i) {
    const t = this.teamTrack;
    if (!t) return;
    // the dots take the short way round the loop
    const n = this.team.length;
    const busy = !!this.tmGlide;
    const at = Math.round(((busy ? this.tmTo : t.scrollLeft) - this.tmBase) / this.tmStep);
    let d = (((i - at) % n) + n) % n;
    if (d > n / 2) d -= n;
    this.teamGlide(this.tmBase + (at + d) * this.tmStep, 900, busy);
    },
    setupTeamDrag() {
    const t = this.teamTrack;
    if (!t) return;
    let down = false, startX = 0, startLeft = 0, lastX = 0, lastT = 0, vel = 0, raf = 0;
    const freeze = () => { t.style.scrollSnapType = 'none'; t.style.scrollBehavior = 'auto'; };
    const release = () => { t.style.scrollSnapType = 'x mandatory'; t.style.scrollBehavior = 'smooth'; };
    const settle = () => {
    const target = this.tmBase + Math.round((t.scrollLeft - this.tmBase) / this.tmStep) * this.tmStep;
    release();
    t.scrollTo({ left: target, behavior: 'smooth' });
    };
    const glide = () => {
    vel *= 0.94;
    t.scrollLeft = this.teamWrap(t.scrollLeft - vel * 16);
    if (Math.abs(vel) < 0.08) { raf = 0; settle(); return; }
    raf = requestAnimationFrame(glide);
    };
    this.onTeamDown = (e) => {
    if (e.pointerType !== 'mouse' || e.button !== 0) return;
    if (raf) { cancelAnimationFrame(raf); raf = 0; }
    if (this.tmGlide) { cancelAnimationFrame(this.tmGlide); this.tmGlide = 0; }
    down = true; this.tmHeld = true; this.tmMoved = false;
    startX = lastX = e.clientX; startLeft = t.scrollLeft; lastT = performance.now(); vel = 0;
    freeze();
    t.classList.add('dragging');
    };
    this.onTeamMove = (e) => {
    if (!down) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 5) this.tmMoved = true;
    t.scrollLeft = this.teamWrap(startLeft - dx);
    const now = performance.now(), dt = now - lastT;
    if (dt > 0) vel = 0.8 * ((e.clientX - lastX) / dt) + 0.2 * vel;
    lastX = e.clientX; lastT = now;
    if (this.tmMoved) e.preventDefault();
    };
    this.onTeamUp = () => {
    if (!down) return;
    down = false; this.tmHeld = false;
    t.classList.remove('dragging');
    if (performance.now() - lastT > 80) vel = 0;
    if (Math.abs(vel) > 0.1) raf = requestAnimationFrame(glide);
    else settle();
    };
    this.onTeamClick = (e) => { if (this.tmMoved) { e.preventDefault(); e.stopPropagation(); this.tmMoved = false; } };
    t.addEventListener('pointerdown', this.onTeamDown);
    t.addEventListener('touchstart', () => { this.teamRecentre(); this.tmHeld = true; }, { passive: true });
    ['touchend', 'touchcancel'].forEach((ev) => t.addEventListener(ev, () => { this.tmHeld = false; this.onTeamScroll(); }, { passive: true }));
    window.addEventListener('pointermove', this.onTeamMove);
    window.addEventListener('pointerup', this.onTeamUp);
    window.addEventListener('pointercancel', this.onTeamUp);
    t.addEventListener('click', this.onTeamClick, true);
    t.addEventListener('dragstart', (e) => e.preventDefault());
    },
    startTeamAuto() {
    const t = this.teamTrack;
    if (!t) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const row = t.closest('.tm-row') || t;
    let hold = false;
    let seen = false;
    const tick = () => { if (seen && !hold && !document.hidden && !this.tmGlide) this.teamMove(1); };
    // only run while the carousel is on screen, and give people a full 5s on the first card when they arrive
    if ('IntersectionObserver' in window) {
    this.ioTeam = new IntersectionObserver((entries) => {
    const vis = entries.some((e) => e.isIntersecting);
    if (vis && !seen) { clearInterval(this.tmAuto); this.tmAuto = setInterval(tick, 5000); }
    seen = vis;
    }, { threshold: 0.4 });
    this.ioTeam.observe(row);
    } else {
    seen = true;
    }
    this.tmAuto = setInterval(tick, 5000);
    this.onTeamHold = () => { hold = true; };
    this.onTeamFree = () => { hold = false; };
    row.addEventListener('pointerenter', this.onTeamHold);
    row.addEventListener('pointerleave', this.onTeamFree);
    row.addEventListener('focusin', this.onTeamHold);
    row.addEventListener('focusout', this.onTeamFree);
    },
    setupSectionSnap() {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const secs = Array.from(document.querySelectorAll('.ev section'));
    if (!secs.length) return;
    // the page may scroll inside a wrapper rather than the window
    let box = null;
    for (let n = secs[0].parentElement; n && !box; n = n.parentElement) {
    const s = getComputedStyle(n);
    if (/(auto|scroll)/.test(s.overflowY) && n.scrollHeight > n.clientHeight) box = n;
    }
    const root = document.scrollingElement || document.documentElement;
    box = box || root;
    const hdr = document.querySelector('.ev header');
    let timer = 0, anim = 0, auto = false;
    const glide = (to) => {
    const from = box.scrollTop;
    const dist = to - from;
    const dur = Math.min(800, 380 + Math.abs(dist) * 0.9);
    const t0 = performance.now();
    const ease = (x) => 1 - Math.pow(1 - x, 3);
    auto = true;
    const frame = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    box.scrollTop = from + dist * ease(k);
    if (k < 1) { anim = requestAnimationFrame(frame); return; }
    anim = 0;
    setTimeout(() => { auto = false; }, 60);
    };
    anim = requestAnimationFrame(frame);
    };
    // once scrolling stops, ease to the nearest section top if it is close; leave tall sections free to read
    const settle = () => {
    const vh = box === root ? window.innerHeight : box.clientHeight;
    if (box.scrollTop + vh >= box.scrollHeight - 4) return;            // at the very bottom (footer showing)
    const off = hdr ? hdr.offsetHeight : 0;
    const base = box === root ? 0 : box.getBoundingClientRect().top;
    let best = null;
    secs.forEach((s) => {
    const d = s.getBoundingClientRect().top - base - off;
    if (d < 0 && s.offsetHeight > vh - off + 40) return;                // inside a section taller than the screen
    if (best === null || Math.abs(d) < Math.abs(best)) best = d;
    });
    if (best === null || Math.abs(best) < 2 || Math.abs(best) > vh * 0.3) return;
    glide(box.scrollTop + best);
    };
    this.onSnapScroll = () => { if (auto) return; clearTimeout(timer); timer = setTimeout(settle, 180); };
    this.onSnapStop = () => { clearTimeout(timer); if (anim) { cancelAnimationFrame(anim); anim = 0; auto = false; } };
    this.snapTarget = box === root ? window : box;
    this.snapTarget.addEventListener('scroll', this.onSnapScroll, { passive: true });
    ['wheel', 'touchstart', 'keydown', 'pointerdown'].forEach((ev) => window.addEventListener(ev, this.onSnapStop, { passive: true }));
    },
    setupNavShrink() {
    const hdr = document.querySelector('.ev header');
    const first = document.querySelector('.ev section');
    if (!hdr || !first) return;
    let box = null;
    for (let n = first.parentElement; n && !box; n = n.parentElement) {
    const s = getComputedStyle(n);
    if (/(auto|scroll)/.test(s.overflowY) && n.scrollHeight > n.clientHeight) box = n;
    }
    const root = document.scrollingElement || document.documentElement;
    box = box || root;
    let last = box.scrollTop, queued = false;
    // scrolling down slims the bar and turns the links into icons; scrolling up brings the words back
    const update = () => {
    queued = false;
    const y = box.scrollTop;
    if (y < 120) hdr.classList.remove('nav-min');
    else if (y > last + 6) hdr.classList.add('nav-min');
    else if (y < last - 6) hdr.classList.remove('nav-min');
    if (Math.abs(y - last) > 6) last = y;
    };
    this.onNavScroll = () => { if (!queued) { queued = true; requestAnimationFrame(update); } };
    this.navTarget = box === root ? window : box;
    this.navTarget.addEventListener('scroll', this.onNavScroll, { passive: true });
    },
    openThanks() {
    const d = document.querySelector('.ev-thanks');
    if (!d) return;
    this.thanksReturn = document.activeElement;
    const f = document.querySelector('#contact form');
    if (f) f.reset();                                   // no sending yet: clear the form and say thanks
    d.classList.remove('open');
    void d.offsetWidth;                                 // restart the animation if it is opened twice
    d.classList.add('open');
    d.setAttribute('aria-hidden', 'false');
    const b = d.querySelector('.btn');
    if (b) setTimeout(() => b.focus({ preventScroll: true }), 60);
    },
    closeThanks() {
    const d = document.querySelector('.ev-thanks');
    if (!d || !d.classList.contains('open')) return;
    d.classList.remove('open');
    d.setAttribute('aria-hidden', 'true');
    if (this.thanksReturn && this.thanksReturn.focus) this.thanksReturn.focus({ preventScroll: true });
    },
    setMenu(open) {
    const hdr = document.querySelector('.ev header');
    const btn = hdr && hdr.querySelector('.menu-btn');
    if (!hdr || !btn) return;
    hdr.classList.toggle('menu-open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    btn.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    this.menuOpen = open;
    this.heroRest();
    },
    toggleMenu() {
    const hdr = document.querySelector('.ev header');
    this.setMenu(!(hdr && hdr.classList.contains('menu-open')));
    },
    openFail(msg) {
    const d = document.querySelector('.ev-fail');
    if (!d) return;
    this.failReturn = document.activeElement;
    const p = d.querySelector('.ev-fail-msg');
    if (p && !this.failDefault) this.failDefault = p.innerHTML;
    if (p) { if (msg) p.textContent = msg; else p.innerHTML = this.failDefault; }
    d.classList.remove('open');
    void d.offsetWidth;
    d.classList.add('open');
    d.setAttribute('aria-hidden', 'false');
    const b = d.querySelector('.btn');
    if (b) setTimeout(() => b.focus({ preventScroll: true }), 60);
    },
    closeFail() {
    const d = document.querySelector('.ev-fail');
    if (!d || !d.classList.contains('open')) return;
    d.classList.remove('open');
    d.setAttribute('aria-hidden', 'true');
    if (this.failReturn && this.failReturn.focus) this.failReturn.focus({ preventScroll: true });
    },
    async submitContact(e) {
      if (this.contactSending) return
      const form = e.target
      const data = Object.fromEntries(new FormData(form))
      this.contactSending = true
      try {
        const res = await fetch('/api/contact', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data),
        })
        const out = await res.json().catch(() => ({}))
        if (!res.ok || !out.ok) { this.openFail(out.message); return }
        this.openThanks()
      } catch (err) {
        this.openFail()
      } finally {
        this.contactSending = false
      }
    },
    teamPrev() { this.teamMove(-1) },
    teamNext() { this.teamMove(1) },
    onTeamScroll() {
      clearTimeout(this.tmIdle)
      this.tmIdle = setTimeout(() => this.teamRecentre(), 140)
      if (this.tmQueued) return
      this.tmQueued = true
      requestAnimationFrame(() => { this.tmQueued = false; this.measureTeam() })
    },
  },
}
</script>
